//! 🧪️ Native registry census borrows the exact registered rows and returns every physical owner under its original caller.
use semio_framework_plugin_window_kits::{AppActionRegistry,RegisteredAppDefinition};
use semio_framework_job::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetirementDemand};
const TURN:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:262144,maximum_depth:4096};
struct Caller{caller:OriginalJobFixtureCaller,decoder:OriginalJobDecodeOwner}
impl Caller{fn receipt(&self)->RetainedCloneProgress{self.caller.receipt()}fn cancel(&self)->&CancelToken{self.caller.cancel()}fn retire(mut self,grant:RetainedCloneGrant){while !self.decoder.terminal_is_empty(){self.caller.turn(grant,|cx|cx.with_original_retirement(|cx|{let d=self.decoder.retirement_demands(grant.maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|self.decoder.close_step(g))?;Ok(())})).unwrap()}self.caller.retire(grant);}}
fn caller()->Caller{Caller{decoder:OriginalJobDecodeOwner::empty(),caller:OriginalJobFixtureCaller::admit(OperationId(77821),Generation(17),RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<26,maximum_release_bytes:1<<27,maximum_depth:4096},default_now_us,u64::MAX,1<<24)}}
fn observed<T>(caller:&mut Caller,grant:RetainedCloneGrant,f:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.caller.turn_with_decoder(grant,&mut caller.decoder,f));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"original registry physical receipts {p:?}, failure {:?}",result.as_ref().err());result.unwrap()}
fn work(caller:&mut Caller,d:RetirementDemand,action:impl FnOnce(RetainedCloneGrant)->Result<RetainedCloneStep,semio_framework_value::ValueError>)->RetainedCloneProgress{observed(caller,TURN,|cx|{let mut slot=None;let grant=cx.retained_grant();admit_original_construction(cx,&mut slot,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let p=action(grant)?.progress();Ok((p,p))})?;Ok(slot.unwrap_or_default())})}
fn fixture()->RegisteredAppDefinition{let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let actions=corpus["actions"].as_array().unwrap().iter().map(|id|semio_framework::ActionDefinition::resumable_framework(id.as_str().unwrap(),semio_framework_ui_locale::LocalizedLabel::native("Adjust","Anpassen"),semio_framework::ActionKind::Mutation,"pencil")).collect();let mut definition=semio_framework_async::poll::resolve_ready(semio_framework_manifest_app_surface::testkit::app_with(actions,Vec::new()));definition.actions.push(semio_framework::ActionDefinition::resumable_framework("adjust",semio_framework_ui_locale::LocalizedLabel::native("Application adjust","Anwendung anpassen"),semio_framework::ActionKind::Mutation,"pencil"));RegisteredAppDefinition::declared(definition,true)}
#[test]
fn native_registry_original_rows_physical_census_denial_and_closure(){for cutoff in [usize::MAX,0,1,2,5,7,12]{let mut source=fixture();source.commit_producer();let pointer=&source.window_kinds.first().actions[0] as *const _ as usize;let mut caller=caller();let mut registry=None;let d=AppActionRegistry::original_birth_demands();for axis in [0,1,4]{let mut grant=TURN;match axis{0=>grant.maximum_items=0,1=>grant.maximum_copy_bytes=0,_=>grant.maximum_depth=0};let p=observed(&mut caller,grant,|cx|{let granted=cx.retained_grant();admit_original_construction(cx,&mut registry,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|_|{let Some((owner,p))=AppActionRegistry::admit_original(source.original_source().unwrap(),granted)?else{unreachable!()};Ok((owner,p))})?;Ok(())});assert!(registry.is_none());let _=p;}
observed(&mut caller,TURN,|cx|{let granted=cx.retained_grant();admit_original_construction(cx,&mut registry,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|_|{let Some((owner,p))=AppActionRegistry::admit_original(source.original_source().unwrap(),granted)?else{unreachable!()};Ok((owner,p))})?;Ok(())});let registry=registry.as_mut().unwrap();let mut steps=0;while !registry.original_index_ready()&&steps<cutoff{let d=registry.original_index_demands().unwrap();if d.capacity_bytes>0{let denied=observed(&mut caller,RetainedCloneGrant{maximum_capacity_bytes:0,..TURN},|cx|{let mut done=None;let granted=cx.retained_grant();admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:0,depth:d.depth},|_|Ok(((),registry.advance_original_index(granted)?.progress())))?;Ok(done)});assert!(denied.is_none())}work(&mut caller,d,|g|registry.advance_original_index(g));steps+=1;assert!(steps<128)}if cutoff==usize::MAX{assert_eq!(registry.controller_id(),"a");assert_eq!(registry.window_body_key("main"),Some("a.main"));assert_eq!(registry.get("adjust").unwrap() as *const _ as usize,pointer);assert!(registry.get("inspect").is_some());}
let d=source.close_demands(4096).unwrap();let before=observed(&mut caller,TURN,|cx|cx.with_original_retirement(|cx|Ok(close_original_retained_step(cx,d,|g|source.close_step(g))?.progress())));assert_eq!(before,RetainedCloneProgress::default());assert!(!source.terminal_is_empty());caller.cancel().cancel_now();for turn in 0..131072{if registry.terminal_is_empty(){break}let d=registry.retirement_demands();if d.release_bytes>0{let p=observed(&mut caller,RetainedCloneGrant{maximum_release_bytes:0,..TURN},|cx|cx.with_original_retirement(|cx|Ok(close_original_retained_turn(cx,d,|g|registry.close_step(g).map_err(Into::into))?.progress())));assert_eq!(p,RetainedCloneProgress::default())}observed(&mut caller,TURN,|cx|cx.with_original_retirement(|cx|{close_original_retained_turn(cx,d,|g|registry.close_step(g).map_err(Into::into))?;Ok(())}));assert!(turn<131071)}assert!(registry.terminal_is_empty());for turn in 0..262144{if source.terminal_is_empty(){break}let d=source.close_demands(4096).unwrap();observed(&mut caller,TURN,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|g|source.close_step(g))?;Ok(())}));assert!(turn<262143,"original registered definition retained its typed payload")}assert!(source.terminal_is_empty());caller.retire(TURN);}}

#[test]
fn original_definition_producer_aborts_before_mount_without_lending_a_registry(){let law:serde_json::Value=serde_json::from_str(include_str!("🏛️producer/🔣️.json")).unwrap();let source=fixture();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||AppActionRegistry::admit_original(source.original_source().unwrap(),TURN));assert_eq!(result.is_ok(),law["visibleBeforeCommit"].as_bool().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(source));assert_eq!(heap.released_bytes>0,law["uncommittedAbortReleasesSource"].as_bool().unwrap());}
#[test]
fn original_registration_fault_survives_assembly_and_startup_with_same_payload(){let law:serde_json::Value=serde_json::from_str(include_str!("🏛️producer/🔣️.json")).unwrap();let fault=&law["fault"];let original=semio_framework::Fault::new(semio_framework::FaultOrigin::Plugin,semio_framework::FaultCode::new(fault["code"].as_str().unwrap()),fault["message"].as_str().unwrap()).with_param("tool",fault["params"]["tool"].as_str().unwrap());let pointer=original.message.as_ptr();let params=original.params.as_ref().unwrap().0[0].1.as_ptr();let assembly=semio_framework_plugin_ownership::sdk_fault::PluginAssemblyError::from_fault(original);assert_eq!(assembly.original.as_ref().unwrap().message.as_ptr(),pointer);let restored=assembly.into_fault();assert_eq!(restored.message.as_ptr(),pointer);assert_eq!(restored.params.as_ref().unwrap().0[0].1.as_ptr(),params);assert_eq!(restored.code.0,fault["code"].as_str().unwrap());}
